 const rows=zones.map(z=>{const es=ev.filter(e=>(e.shotPosition?.zone||'nondefinito')===z);const data=shotMetrics(es);return `<tr><td>${zoneName(z)}</td><td>${data.goals}</td><td>${data.missed}</td><td>${data.conceded}</td><td>${data.saves}</td></tr>`}).join('');
