function saveMatch(){state.match.seasonId=state.currentSeasonId;const snap=JSON.parse(JSON.stringify({...state,saved:[]}));state.saved.unshift({id:uid(),seasonId:state.currentSeasonId,teamName:state.settings.teamName,opponent:state.opponent.name,home:state.home,match:JSON.parse(JSON.stringify(state.match)),snapshot:snap,savedAt:new Date().toISOString()});save();renderArchive();toast('Partita salvata')}
function openMatchData(){const m=state.match;$('mDate').value=m.date||'';$('mTime').value=m.time||'';$('mCompetitionType').value=m.competitionType||'';$('mCompetition').value=m.competition||'';$('mEncounter').value=m.encounter||'';$('mFacility').value=m.facility||m.venue||'';$('mDelegate').value=m.delegate||'';$('mRef1').value=m.ref1||'';$('mRef2').value=m.ref2||'';$('homeAwayCheck').checked=!state.home;$('homeBtn').classList.toggle('selected',state.home);$('awayBtn').classList.toggle('selected',!state.home);$('matchDialog').showModal()}
function saveMatchData(){state.home=!$('homeAwayCheck').checked;state.match={seasonId:state.currentSeasonId,date:$('mDate').value,time:$('mTime').value,competitionType:$('mCompetitionType').value.trim(),competition:$('mCompetition').value.trim(),encounter:$('mEncounter').value.trim(),facility:$('mFacility').value.trim(),venue:$('mFacility').value.trim(),delegate:$('mDelegate').value.trim(),ref1:$('mRef1').value.trim(),ref2:$('mRef2').value.trim()};save();closeDialog('matchDialog');renderAll();toast(state.home?'Incontro impostato CASA':'Incontro impostato FUORI CASA')}
function openConv(){const active=state.athletes.filter(a=>!a.archived);$('convList').innerHTML=`<div class="conv-toolbar"><strong>Seleziona le atlete</strong><span id="convLiveCount">${state.selected.length}/15</span></div>`+active.map(a=>`<label class="conv-card ${state.selected.includes(a.id)?'selected':''}"><input type="checkbox" data-conv="${a.id}" ${state.selected.includes(a.id)?'checked':''}><span class="conv-check">✓</span>${capHtml(a,'mini')}<span class="conv-copy"><b>${esc(a.name)}</b><small>${esc(a.role||'Atleta')}</small></span></label>`).join('');$('convDialog').showModal();document.querySelectorAll('[data-conv]').forEach(x=>x.onchange=()=>{if(document.querySelectorAll('[data-conv]:checked').length>15){x.checked=false;toast('Massimo 15 convocate')}x.closest('.conv-card').classList.toggle('selected',x.checked);const c=document.querySelectorAll('[data-conv]:checked').length;const el=$('convLiveCount');if(el)el.textContent=`${c}/15`})}
function saveConv(){state.selected=[...document.querySelectorAll('[data-conv]:checked')].map(x=>x.dataset.conv).slice(0,15);save();closeDialog('convDialog');renderAll();toast('Convocazione salvata')}
function openSettings(){ $('sTeam').value=state.settings.teamName;$('sOpp').value=state.opponent.name;$('sColor').value=state.settings.primary;$('teamLogoPreview').innerHTML=state.settings.teamLogo?`<img src="${state.settings.teamLogo}">`:'';$('oppLogoPreview').innerHTML=state.opponent.logo?`<img src="${state.opponent.logo}">`:'';renderManager();$('settingsDialog').showModal()}
function readImage(input,cb){const f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)}
function renderManager(){$('rosterManager').innerHTML=state.athletes.map(a=>`<div class="manager-row ${a.archived?'muted':''}">${capHtml(a,'mini')}<input data-name="${a.id}" value="${esc(a.name)}"><input data-cap="${a.id}" value="${esc(a.cap)}"><select data-role="${a.id}"><option value="" ${!a.role?'selected':''}>Atleta</option><option value="Portiere" ${a.role==='Portiere'?'selected':''}>Portiere</option></select><button class="icon-btn mini" data-archive="${a.id}">${a.archived?'↩':'⌁'}</button></div>`).join('')||'<div class="empty">Nessuna atleta.</div>';document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{const a=athlete(b.dataset.archive);a.archived=!a.archived;if(a.archived)state.selected=state.selected.filter(id=>id!==a.id);save();renderManager();renderPlayers();})}
function saveSettings(){state.settings.teamName=$('sTeam').value.trim()||'Squadra';state.opponent.name=$('sOpp').value.trim()||'Avversaria';state.settings.primary=$('sColor').value;document.querySelectorAll('[data-name]').forEach(i=>{const a=athlete(i.dataset.name);if(a)a.name=i.value.trim()||a.name});document.querySelectorAll('[data-cap]').forEach(i=>{const a=athlete(i.dataset.cap);if(a)a.cap=i.value.trim()||a.cap});document.querySelectorAll('[data-role]').forEach(i=>{const a=athlete(i.dataset.role);if(a)a.role=i.value});save();closeDialog('settingsDialog');renderAll();toast('Dati salvati')}
function addAthlete(){let n=state.athletes.length+1;state.athletes.push({id:uid(),name:`Atleta ${n}`,cap:String(n),role:'',archived:false});save();renderManager();}
function showPage(p){['match','stats','archive'].forEach(x=>{$(`${x}Page`).classList.toggle('hidden',x!==p)});document.querySelectorAll('.tab').forEach(b=>b.classList.remove('active'));$(`tab${p[0].toUpperCase()+p.slice(1)}`).classList.add('active');if(p==='stats'){renderStats();renderSavedStats();installMultiExportButton()}if(p==='archive')renderArchive()}
function closeDialog(id){$(id).close?.();$(id).removeAttribute('open')}

function renderGoalkeeperStats(){
 const box=$('goalkeeperStats');if(!box)return;
 const keepers=selected().filter(a=>a.role==='Portiere'||isRed(a.cap));
 const assigned=keepers.reduce((n,a)=>n+shotMetrics(state.events,a.id).conceded,0);
 const total=shotMetrics().conceded,unassigned=Math.max(0,total-assigned);
 box.innerHTML=keepers.map(a=>{const es=state.events.filter(e=>e.athleteId===a.id&&e.kind==='shot'&&e.team==='against');const d=shotMetrics(es);return `<div class="goalkeeper-card">${capHtml(a,'mini')}<div><strong>${esc(a.name)}</strong><small>Portiere · ${d.received} tiri ricevuti</small></div><div class="keeper-number"><span>SUBITI</span><b>${d.conceded}</b></div><div class="keeper-number"><span>PARATE</span><b>${d.saves}</b></div><div class="keeper-number"><span>PARI</span><b>${shotMetrics(es.filter(e=>e.situation==='even')).conceded}</b></div><div class="keeper-number danger-number"><span>UOMO IN MENO</span><b>${shotMetrics(es.filter(e=>e.situation==='manDown')).conceded}</b></div></div>`}).join('')||'<div class="empty">Imposta un portiere nella rosa.</div>';
 if(unassigned)box.innerHTML+=`<div class="event-warning">Attenzione: ${unassigned} goal subiti assegnati a un'atleta non identificata come portiere. Correggi gli eventi per allineare il dettaglio portieri al totale squadra (${total}).</div>`;
}
function renderExtendedStats(){
 const table=$('statsTable');if(!table)return;
 table.innerHTML=selected().map(a=>{const es=state.events.filter(e=>e.athleteId===a.id),d=shotMetrics(es),count=(kind,key,value)=>es.filter(e=>e.kind===kind&&e[key]===value).length;
 return `<tr><td>${esc(a.name)}</td><td>${d.goals}</td><td>${d.conceded}</td><td>${d.shots}</td><td>${d.missed}</td><td>${d.outside}</td><td>${d.received}</td><td>${d.saves}</td><td>${d.efficiency}%</td><td>${shotMetrics(es.filter(e=>e.situation==='power')).goals}</td><td>${shotMetrics(es.filter(e=>e.situation==='even')).goals}</td><td>${shotMetrics(es.filter(e=>e.situation==='counter')).goals}</td><td>${count('assist','assistType','goal')}</td><td>${count('exclusion','exclusionSide','against')}</td><td>${count('ball','ballType','won')}</td><td>${count('ball','ballType','lost')}</td><td>${count('counterfoul','counterfoulType','won')}</td><td>${count('counterfoul','counterfoulType','suffered')}</td></tr>`}).join('');
}
function zoneForPoint(x,y){
 if(x<12||x>88||y<16||y>79)return 'fuori';
 return `${y<47?'alto':'basso'}-${x<37?'sx':x<63?'centro':'dx'}`;
}
function showGoalMap(){
 if(currentKind!=='shot')return;
 const dialog=$('goalMapDialog');const dot=$('goalMapDot');const info=$('goalMapInfo');
 if(shotPosition){for(const id of ['goalMapDot','goalMapDotInner']){$(id).setAttribute('cx',shotPosition.x);$(id).setAttribute('cy',shotPosition.y);$(id).style.display='';}info.textContent=`Posizione registrata: ${shotPosition.zone}`;}else{dot.style.display='none';$('goalMapDotInner').style.display='none';info.textContent='Tocca il punto del tiro, anche fuori dai pali.';}
 dialog.showModal();
}
function selectGoalPoint(e){
 const svg=$('goalMapSvg'),r=svg.getBoundingClientRect();if(!r.width||!r.height)return;
 const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const matrix=svg.getScreenCTM();if(!matrix)return;const mapped=point.matrixTransform(matrix.inverse());
 const x=Number(Math.max(0,Math.min(100,mapped.x)).toFixed(1));
 const y=Number(Math.max(0,Math.min(100,mapped.y)).toFixed(1));
 shotPosition={x,y,zone:zoneForPoint(x,y)};
 if(shotPosition.zone==='fuori'){shotOutcome='Fuori';}else if(shotOutcome==='Fuori'){shotOutcome=($('eventRole').dataset.role==='Portiere'?'Parata':'Parato');}
 for(const id of ['goalMapDot','goalMapDotInner']){$(id).setAttribute('cx',x);$(id).setAttribute('cy',y);$(id).style.display='';}$('goalMapInfo').textContent=`${shotPosition.zone==='fuori'?'Tiro fuori porta':'Zona: '+shotPosition.zone} · ${shotOutcome}`;
}


function fieldZoneForPoint(x,y){
 const row=y<33.333?'Attacco':y<66.667?'Centrocampo':'Difesa';
 const col=x<33.333?'sinistra':x<66.667?'centro':'destra';
 return `${row} · ${col}`;
}
function displayFieldDot(){
 const dot=$('fieldMapDot'),halo=$('fieldMapDotHalo'),info=$('fieldMapInfo');
 if(!fieldPosition){dot.style.display='none';halo.style.display='none';info.textContent='Tocca il campo per segnare la posizione';return;}
 const x=30+fieldPosition.x*2.6,y=40+fieldPosition.y*4.4;
 for(const element of [dot,halo]){element.setAttribute('cx',x);element.setAttribute('cy',y);element.style.display='';}
 info.textContent='Posizione selezionata: '+fieldPosition.zone;
}
function showFieldMap(){if(currentKind!=='counterfoul')return;displayFieldDot();$('fieldMapDialog').showModal();}
function selectFieldPoint(e){
 const svg=$('fieldMapSvg'),matrix=svg.getScreenCTM();if(!matrix)return;
 const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const mapped=pt.matrixTransform(matrix.inverse());
 const x=Number((Math.max(30,Math.min(290,mapped.x))-30)/2.6).toFixed(1);
 const y=Number((Math.max(40,Math.min(480,mapped.y))-40)/4.4).toFixed(1);
 fieldPosition={x,y,zone:fieldZoneForPoint(x,y)};displayFieldDot();
}
function renderCounterfoulMapStats(){
 const host=$('counterfoulMapStats');if(!host)return;
 const events=state.events.filter(e=>e.kind==='counterfoul');
 const zoneLabels=['Attacco','Centrocampo','Difesa'].flatMap(row=>['sinistra','centro','destra'].map(col=>row+' · '+col));zoneLabels.push('Non localizzato');
 const rows=zoneLabels.map(zone=>{const filtered=events.filter(e=>(e.fieldPosition?.zone||'Non localizzato')===zone);const won=filtered.filter(e=>e.counterfoulType==='won').length;const suffered=filtered.filter(e=>e.counterfoulType==='suffered').length;return `<tr><td>${esc(zone)}</td><td>${won}</td><td>${suffered}</td><td>${won+suffered}</td></tr>`}).join('');
 const individual=selected().flatMap(a=>zoneLabels.map(zone=>{const filtered=events.filter(e=>e.athleteId===a.id&&(e.fieldPosition?.zone||'Non localizzato')===zone);if(!filtered.length)return '';return `<tr><td>${esc(a.cap)}</td><td>${esc(a.name)}</td><td>${esc(zone)}</td><td>${filtered.filter(e=>e.counterfoulType==='won').length}</td><td>${filtered.filter(e=>e.counterfoulType==='suffered').length}</td></tr>`})).filter(Boolean).join('');
 host.innerHTML=statsMapUI('field')+`<div class="table-scroll"><table class="field-stats-table"><thead><tr><th>Zona del campo</th><th>Guadagnati</th><th>Subiti</th><th>Totale</th></tr></thead><tbody>${rows}</tbody></table></div><div class="section-title"><div><h3>Dettaglio individuale per zona</h3><p>La posizione di ogni controfallo è associata all'atleta che lo ha registrato.</p></div></div><div class="table-scroll"><table class="field-stats-table"><thead><tr><th>Calotta</th><th>Atleta</th><th>Zona</th><th>Guadagnati</th><th>Subiti</th></tr></thead><tbody>${individual||'<tr><td colspan="5">Nessun controfallo registrato</td></tr>'}</tbody></table></div><small class="map-note">Gli eventi precedenti senza punto sono indicati come “Non localizzato”.</small>`;
}


// I punti nelle mappe derivano esclusivamente dagli eventi, senza contatori separati.
let mapFilters={shot:'all',field:'all'};
const statColors={goal:'#4ade80',miss:'#ffb454',received:'#fb7185',save:'#67d3ff',outside:'#e5e7eb',cfWon:'#7ee787',cfSuffered:'#ff8c91'};
function statsSvgCopy(source){
 const sourceSvg=$(source);if(!sourceSvg)return '';
 let svg=sourceSvg.outerHTML.replace(/\sid="[^"]*"/g,m=>m.replace('id="','id="stat-'));
 svg=svg.replace(/url\(#/g,'url(#stat-').replace(/href="#/g,'href="#stat-').replace(/<svg /,'<svg aria-hidden="true" class="stats-map-plot" ');
 return svg.replace(/<\/svg>$/,'<g class="stats-map-points"></g></svg>');
}
function statsMapEvents(type){
 const key=mapFilters[type]||'all';
 return state.events.filter(e=>type==='shot'?e.kind==='shot':e.kind==='counterfoul').filter(e=>key==='all'||String(e.athleteId)===key);
}
function plotType(e,type){
 if(type==='field')return e.counterfoulType==='won'?'cfWon':'cfSuffered';
 if(e.team==='against')return isGoalEvent(e)?'received':'save';
 if(isGoalEvent(e))return 'goal';
 return e.outcome==='Fuori'||e.shotPosition?.zone==='fuori'?'outside':'miss';
}
function mapPoint(e,type){
 const p=type==='shot'?e.shotPosition:e.fieldPosition;
 if(!p||!Number.isFinite(Number(p.x))||!Number.isFinite(Number(p.y)))return null;
 const x=Number(p.x),y=Number(p.y);
 return type==='shot'?[Math.min(100,Math.max(0,x)),Math.min(100,Math.max(0,y))]:[30+Math.min(100,Math.max(0,x))*2.6,40+Math.min(100,Math.max(0,y))*4.4];
}
function statsMapUI(type){
 const events=statsMapEvents(type), withPoint=events.filter(e=>mapPoint(e,type)), missing=events.length-withPoint.length;
 const items=type==='shot'?[['goal','Gol fatti'],['miss','Tiri sbagliati'],['outside','Tiri fuori'],['received','Gol subiti'],['save','Parate']]:[['cfWon','Controfalli guadagnati'],['cfSuffered','Controfalli subiti']];
 const names=state.athletes.filter(a=>!a.archived||state.events.some(e=>e.athleteId===a.id));
 const options='<option value="all">Tutta la squadra</option>'+names.map(a=>`<option value="${esc(a.id)}" ${String(mapFilters[type])===String(a.id)?'selected':''}>#${esc(a.cap)} ${esc(a.name)}</option>`).join('');
 const svg=statsSvgCopy(type==='shot'?'goalMapSvg':'fieldMapSvg');
 const plotted=withPoint.map(e=>{
  const [x,y]=mapPoint(e,type),t=plotType(e,type),label=type==='shot'?(e.shotPosition?.zone||'Tiro'):(e.fieldPosition?.zone||'Controfallo');
  return `<circle cx="${x}" cy="${y}" r="${type==='shot'?1.5:5}" fill="${statColors[t]}" stroke="#072033" stroke-width="${type==='shot'?.35:1.5}" opacity=".92"><title>${esc(label)} · ${esc(t)}</title></circle>`;
 }).join('');
 const shownSvg=svg.replace('<g class="stats-map-points"></g>','<g class="stats-map-points">'+plotted+'</g>');
 const label=type==='shot'?'Porta · distribuzione dei tiri':'Campo · distribuzione dei controfalli';
 return `<div class="stats-map-options"><label>Visualizza<select data-stats-map-filter="${type}">${options}</select></label><span class="stats-map-count">${withPoint.length} punti visualizzati · ${missing} non localizzati</span></div><div class="stats-map-layout"><div class="stats-map-card"><h3>${label}</h3>${shownSvg}<div class="stats-dot-legend">${items.map(([key,name])=>`<span><b style="background:${statColors[key]}"></b>${name}</span>`).join('')}</div></div><div class="stats-map-card"><h3>Riepilogo selezione</h3>${items.map(([key,name])=>`<div class="legend"><span>${name}</span><strong>${events.filter(e=>plotType(e,type)===key).length}</strong></div>`).join('')}<div class="legend"><span>Eventi senza posizione</span><strong>${missing}</strong></div><p class="map-note">I punti sono ricavati direttamente dagli eventi registrati. Le statistiche non cambiano quando applichi un filtro.</p></div></div>`;
}
function updateStatsMapFilter(e){if(!e.target.matches('[data-stats-map-filter]'))return;const type=e.target.dataset.statsMapFilter;mapFilters[type]=e.target.value;type==='shot'?renderShotMapStats():renderCounterfoulMapStats();}
document.addEventListener('change',updateStatsMapFilter);
function playerReportMatches(scope){
 if(scope==='match')return [{match:state.match,opponent:state.opponent.name,snapshot:{events:state.events,athletes:state.athletes,selected:state.selected}}];
 return (state.saved||[]).filter(s=>getSavedStatsSnapshot(s));
}
function playerReportRows(scope,id){
 const current=athlete(id),matches=playerReportMatches(scope);if(!current)return [];
 return matches.map(s=>{
  const snap=getSavedStatsSnapshot(s)||{},athletes=snap.athletes||[],player=athletes.find(a=>a.id===id)||athletes.find(a=>a.cap===current.cap&&a.name.toLocaleLowerCase()===current.name.toLocaleLowerCase());
  if(!player)return null;
  const ids=Array.isArray(snap.selected)?snap.selected:athletes.map(a=>a.id);if(!ids.includes(player.id))return null;
  const es=(snap.events||[]).filter(e=>e.athleteId===player.id);
  const own=es.filter(e=>e.kind==='shot'&&e.team==='own');const against=es.filter(e=>e.kind==='shot'&&e.team==='against');
  const goals=own.filter(isGoalEvent).length,received=against.length;
  const counter=e=>es.filter(x=>x.kind==='counterfoul'&&x.counterfoulType===e).length;
  return {date:s.match?.date||snap.match?.date||'',opponent:s.opponent||snap.opponent?.name||'Avversaria',shots:own.length,goals,missed:own.length-goals,outside:own.filter(e=>e.outcome==='Fuori'||e.shotPosition?.zone==='fuori').length,received,conceded:against.filter(isGoalEvent).length,saves:against.filter(e=>e.outcome==='Parata').length,assists:es.filter(e=>e.kind==='assist'&&e.assistType==='goal').length,exAgainst:es.filter(e=>e.kind==='exclusion'&&e.exclusionSide==='against').length,exFor:es.filter(e=>e.kind==='exclusion'&&e.exclusionSide==='for').length,ballsWon:es.filter(e=>e.kind==='ball'&&e.ballType==='won').length,ballsLost:es.filter(e=>e.kind==='ball'&&e.ballType==='lost').length,cfWon:counter('won'),cfSuffered:counter('suffered')};
 }).filter(Boolean);
}
const playerFields=[['date','Data'],['opponent','Avversaria'],['goals','Goal fatti'],['conceded','Goal subiti'],['shots','Tiri'],['missed','Tiri sbagliati'],['outside','Tiri fuori'],['received','Tiri ricevuti'],['saves','Parate'],['assists','Assist goal'],['exAgainst','Esp. subite'],['exFor','Esp. guadagnate'],['ballsWon','Palle guadagnate'],['ballsLost','Palle perse'],['cfWon','Controfalli guadagnati'],['cfSuffered','Controfalli subiti']];
function playerReportTotal(rows){const total={};playerFields.slice(2).forEach(([key])=>total[key]=rows.reduce((sum,row)=>sum+Number(row[key]||0),0));return total;}
function playerReportData(){const id=$('playerReportSelect')?.value,scope=$('playerReportScope')?.value||'match';return {a:athlete(id),scope,rows:playerReportRows(scope,id)};}
function renderPlayerReport(){
 const select=$('playerReportSelect'),preview=$('playerReportPreview');if(!select||!preview)return;
 const old=select.value;select.innerHTML=state.athletes.filter(a=>!a.archived||state.events.some(e=>e.athleteId===a.id)).map(a=>`<option value="${esc(a.id)}">#${esc(a.cap)} · ${esc(a.name)}</option>`).join('');if([...select.options].some(o=>o.value===old))select.value=old;
 const {rows,scope}=playerReportData(),tot=playerReportTotal(rows);
 preview.innerHTML=`<strong>${rows.length} ${rows.length===1?'partita':'partite'} · ${scope==='match'?'Partita aperta':'Archivio completo'}</strong><div class="stats-summary compact">${[['Goal',tot.goals],['Tiri',tot.shots],['% goal',tot.shots?Math.round(tot.goals/tot.shots*100)+'%':'0%'],['Gol subiti',tot.conceded],['Parate',tot.saves],['Assist',tot.assists],['Controfalli +',tot.cfWon],['Controfalli −',tot.cfSuffered]].map(([k,v])=>`<div class="stat-big"><span>${k}</span><strong>${v||0}</strong></div>`).join('')}</div>`;
}
function exportPlayerCSV(){const {a,scope,rows}=playerReportData();if(!a)return;const totals=playerReportTotal(rows);const fields=playerFields;const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const body=[['Atleta',a.name],['Calotta',a.cap],['Periodo',scope==='match'?'Partita corrente':'Globale archivio'],[],fields.map(x=>x[1]),...rows.map(r=>fields.map(([k])=>r[k])),['TOTALE','',...fields.slice(2).map(([k])=>totals[k])]].map(arr=>arr.map(q).join(';')).join('\r\n');const blob=new Blob(['\ufeff'+body],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`Match-statistiche-${a.name.replace(/[^a-z0-9_-]+/gi,'-')}-${scope}.csv`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Statistiche atleta esportate in CSV');}
function exportPlayerPDF(){const {a,scope,rows}=playerReportData();if(!a)return;if(!window.jspdf?.jsPDF){toast('Generatore PDF non disponibile');return;}const doc=new window.jspdf.jsPDF({format:'a4',unit:'mm'});doc.setFillColor(11,33,51);doc.rect(0,0,210,32,'F');doc.setTextColor(255);doc.setFont('helvetica','bold');doc.setFontSize(17);doc.text('MATCH · STATISTICHE INDIVIDUALI',13,14);doc.setFontSize(10);doc.text(`#${a.cap} ${a.name} · ${scope==='match'?'Singola partita':'Globale archivio'}`,13,23);doc.setTextColor(20,40,55);const total=playerReportTotal(rows);doc.autoTable({startY:40,head:[['Indicatore','Totale']],body:playerFields.slice(2).map(([key,label])=>[label,total[key]]).concat([['Partite analizzate',rows.length],['Efficacia tiro',total.shots?`${(100*total.goals/total.shots).toFixed(1)}%`:'0%']]),headStyles:{fillColor:[28,66,101]},styles:{fontSize:9,cellPadding:2.1}});const body=rows.map(r=>[r.date,r.opponent,r.goals,r.shots,r.conceded,r.saves,r.assists,r.cfWon,r.cfSuffered]);doc.autoTable({startY:doc.lastAutoTable.finalY+10,head:[['Data','Avversaria','Gol','Tiri','Subiti','Par.','Assist','CF+','CF-']],body:body.length?body:[['—','Nessuna partita',0,0,0,0,0,0,0]],headStyles:{fillColor:[28,66,101]},styles:{fontSize:7,cellPadding:1.7}});doc.save(`Match-statistiche-${a.name.replace(/[^a-z0-9_-]+/gi,'-')}-${scope}.pdf`);toast('PDF atleta esportato');}
document.addEventListener('change',e=>{if(e.target.id==='playerReportSelect'||e.target.id==='playerReportScope')renderPlayerReport();});
