function reportTitle(){
  const m=state.match||{};
  return `${state.settings.teamName||'Squadra'} ${state.home?'vs':'@'} ${state.opponent.name||'Avversaria'}`;
}
function fmtDate(v){if(!v)return '';try{return new Date(v+'T00:00:00').toLocaleDateString('it-IT')}catch{return v}}
function reportMeta(){
  const m=state.match||{};
  return [
    ['Data',fmtDate(m.date)],['Ora partita',m.time||''],['Tipo campionato',m.competitionType||''],
    ['Campionato / Girone',m.competition||''],['Incontro',m.encounter||`${state.home?state.settings.teamName:state.opponent.name} vs ${state.home?state.opponent.name:state.settings.teamName}`],
    ['Impianto / Piscina',m.facility||m.venue||''],['Delegato',m.delegate||''],['Arbitro 1',m.ref1||''],['Arbitro 2',m.ref2||''],['Sede',state.home?'CASA':'FUORI CASA']
  ];
}
function reportLogo(src,alt){return src?`<img class="report-logo" src="${src}" alt="${esc(alt)}">`:''}
function reportRowsEvents(){
  const ev=[...state.events].sort((a,b)=>Number(a.period)-Number(b.period)||String(a.time||'').localeCompare(String(b.time||'')));
  return ev.map(e=>{const a=athlete(e.athleteId);return `<tr><td>${esc(e.period||'')}</td><td>${esc(e.time||'')}</td><td>${esc(a?.cap||'')}</td><td>${esc(a?.name||'Atleta')}</td><td>${esc(eventLabel(e))}</td><td>${esc(e.team==='against'?'Subito':'Fatto')}</td><td>${esc([e.shotPosition?.zone?'Porta: '+e.shotPosition.zone:'',e.fieldPosition?.zone?'Campo: '+e.fieldPosition.zone:'',e.note||''].filter(Boolean).join(' · '))}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty-cell">Nessun evento registrato</td></tr>';
}
function reportRowsAthletes(){
  return selected().map(a=>{const es=state.events.filter(e=>e.athleteId===a.id);const gs=es.filter(e=>e.kind==='shot'&&e.team==='own'&&isGoalEvent(e)).length;const ts=es.filter(e=>e.kind==='shot'&&e.team==='own').length;const sup=es.filter(e=>e.kind==='shot'&&e.situation==='power'&&e.outcome==='Goal').length;const pari=es.filter(e=>e.kind==='shot'&&e.situation==='even'&&e.outcome==='Goal').length;const cp=es.filter(e=>e.kind==='shot'&&e.situation==='counter'&&e.outcome==='Goal').length;const assists=es.filter(e=>e.kind==='assist').length;const ex=es.filter(e=>e.kind==='exclusion').length;const conceded=es.filter(e=>e.kind==='shot'&&e.team==='against'&&isGoalEvent(e)).length;return `<tr><td>${esc(a.cap)}</td><td>${esc(a.name)}</td><td>${esc(a.role||'Atleta')}</td><td>${gs}</td><td>${conceded}</td><td>${ts}</td><td>${ts?Math.round(gs/ts*100):0}%</td><td>${sup}</td><td>${pari}</td><td>${cp}</td><td>${assists}</td><td>${ex}</td></tr>`}).join('')||'<tr><td colspan="12" class="empty-cell">Nessuna convocata</td></tr>';
}
function reportRowsTimeouts(){
  return state.timeouts.map((t,i)=>`<tr><td>Time-out ${i+1}</td><td>${esc(t?.period?`${t.period}° tempo`:'—')}</td><td>${esc(t?.time||'—')}</td></tr>`).join('');
}
