function makePdf(lines){const chunks=[];for(let i=0;i<lines.length;i+=52)chunks.push(lines.slice(i,i+52));if(!chunks.length)chunks.push(['Referto Pallanuoto']);const fontId=3+chunks.length*2,objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';objects[2]=`<< /Type /Pages /Kids [${chunks.map((_,i)=>`${3+i*2} 0 R`).join(' ')}] /Count ${chunks.length} >>`;chunks.forEach((page,i)=>{const pageId=3+i*2,contentId=pageId+1;objects[pageId]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`;const stream=`BT /F1 9 Tf 38 805 Td 13 TL ${page.map(x=>`(${pdfSafe(x).slice(0,108)}) Tj T*`).join(' ')} ET`;objects[contentId]=`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`});objects[fontId]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';let pdf='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=pdf.length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`}const xref=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)pdf+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'})}
