function xmlEsc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
function xCell(v,style='sText',type='String'){return `<Cell ss:StyleID="${style}"><Data ss:Type="${type}">${xmlEsc(v)}</Data></Cell>`}
function xRow(cells){return `<Row>${cells.join('')}</Row>`}
function excelSheet(name,rows){
  const widths=rows[0]?.map(()=>80)||[];
  return `<Worksheet ss:Name="${xmlEsc(name)}"><Table>${rows.map(r=>xRow(r)).join('')}</Table><WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel"><PageSetup><Layout x:Orientation="Landscape"/><PageMargins x:Top="0.35" x:Bottom="0.35" x:Left="0.3" x:Right="0.3"/></PageSetup><FitToPage/><Print><ValidPrinterInfo/><PaperSizeIndex>9</PaperSizeIndex><HorizontalResolution>600</HorizontalResolution><VerticalResolution>600</VerticalResolution><FitWidth>1</FitWidth><FitHeight>0</FitHeight></Print><Selected/></WorksheetOptions></Worksheet>`;
}
