const openEventBase=openEvent;
openEvent=function(id,eventId=null){openEventBase(id,eventId);const a=athlete(currentAthlete);if((a?.role==='Portiere'||isRed(a?.cap))&&currentEvent?.team==='against'&&shotOutcome==='Goal'){shotOutcome='Goal subito';renderEventPanel()}};
function ensureCompetitionTypes(){const select=$('mCompetitionType');['Euro Cup','Champions League','Conference Cup','Challenger Cup'].forEach(name=>{if(![...select.options].some(o=>o.value===name))select.add(new Option(name,name))})}
function encounterValue(home=state.home){const team=state.settings.teamName||'Squadra';const opponent=$('mOpponent')?.value.trim()||state.opponent.name||'Avversaria';return home?`${team} vs ${opponent}`:`${opponent} vs ${team}`}
function updateEncounterField(home=state.home){$('mEncounter').value=encounterValue(home)}
const openMatchDataBase=openMatchData;
openMatchData=function(){ensureCompetitionTypes();openMatchDataBase();$('mOpponent').value=state.opponent.name||'';$('matchOppLogoPreview').innerHTML=state.opponent.logo?`<img src="${state.opponent.logo}">`:'';updateEncounterField(state.home)};
const saveMatchDataBase=saveMatchData;
saveMatchData=function(){state.opponent.name=$('mOpponent').value.trim()||'Avversaria';updateEncounterField(!$('homeAwayCheck').checked);saveMatchDataBase()};
$('mOppLogo').onchange=()=>readImage($('mOppLogo'),v=>{state.opponent.logo=v;$('matchOppLogoPreview').innerHTML=`<img src="${v}">`;save()});
$('mOpponent').addEventListener('input',()=>updateEncounterField(!$('homeAwayCheck').checked));
$('homeBtn').addEventListener('click',()=>updateEncounterField(true));
$('awayBtn').addEventListener('click',()=>updateEncounterField(false));
$('homeAwayCheck').addEventListener('change',()=>updateEncounterField(!$('homeAwayCheck').checked));
$('saveMatchBtn').onclick=saveMatch;
// events UI
$('eventKinds').querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{currentKind=b.dataset.kind;renderEventPanel()});$('saveEvent').onclick=saveEvent;$('exportPdfBtn').onclick=exportPDF;$('exportExcelBtn').onclick=exportExcel;$('deleteEvent').onclick=deleteEvent;$('shareBtn').onclick=()=>{const text=`${state.settings.teamName} vs ${state.opponent.name}\n${calc().own}-${calc().against}`;navigator.share?navigator.share({title:'Referto',text}):navigator.clipboard?.writeText(text).then(()=>toast('Copiato'))};
// tabs
$('tabMatch').onclick=()=>showPage('match');$('tabStats').onclick=()=>showPage('stats');$('tabArchive').onclick=()=>showPage('archive');
$('matchDataBtn').onclick=openMatchData;$('saveMatchData').onclick=saveMatchData;$('convocationBtn').onclick=openConv;$('saveConv').onclick=saveConv;$('settingsBtn').onclick=openSettings;$('addAthlete').onclick=addAthlete;$('saveSettings').onclick=saveSettings;$('manageRosterBtn').onclick=openSettings;$('saveMatchData').onclick=saveMatchData;$('homeBtn').onclick=()=>{state.home=true;$('homeAwayCheck').checked=false;$('homeBtn').classList.add('selected');$('awayBtn').classList.remove('selected');save();renderHeader();renderPlayers()};$('awayBtn').onclick=()=>{state.home=false;$('homeAwayCheck').checked=true;$('awayBtn').classList.add('selected');$('homeBtn').classList.remove('selected');save();renderHeader();renderPlayers()};$('homeAwayCheck').onchange=()=>{state.home=!$('homeAwayCheck').checked;$('homeBtn').classList.toggle('selected',state.home);$('awayBtn').classList.toggle('selected',!state.home);save();renderHeader();renderPlayers();renderScore()};$('newMatchBtn').onclick=()=>{if(confirm('Creare una nuova partita?')){const t=state.settings.teamName;state.match={seasonId:state.currentSeasonId,date:new Date().toISOString().slice(0,10),time:'',competitionType:'',competition:'',encounter:'',facility:'',venue:'',delegate:'',ref1:'',ref2:''};state.opponent={name:'Avversaria',logo:''};state.home=true;state.selected=state.athletes.filter(a=>!a.archived).slice(0,15).map(a=>a.id);state.events=[];state.timeouts=[null,null];save();renderAll();toast('Nuova partita')}};$('backupExport').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`referto-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};$('backupImportBtn').onclick=()=>$('backupImport').click();$('backupImport').onchange=()=>{const f=$('backupImport').files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x.settings||!Array.isArray(x.athletes))throw 0;state={...empty(),...x};if(!Array.isArray(state.seasons)||!state.seasons.length)state.seasons=[{id:'season-default',name:'2026/2027'}];state.currentSeasonId=state.currentSeasonId&&state.seasons.some(q=>q.id===state.currentSeasonId)?state.currentSeasonId:state.seasons[0].id;state.match=state.match||{};state.match.seasonId=state.match.seasonId&&state.seasons.some(q=>q.id===state.match.seasonId)?state.match.seasonId:state.currentSeasonId;(state.saved||[]).forEach(q=>{if(!q.seasonId)q.seasonId=state.currentSeasonId;if(q.snapshot&&!q.snapshot.seasonId)q.snapshot.seasonId=q.seasonId});save();renderAll();toast('Backup importato')}catch{toast('Backup non valido')}};r.readAsText(f)};
$('seasonSelect').onchange=()=>{state.currentSeasonId=$('seasonSelect').value;state.match.seasonId=state.currentSeasonId;saveSeasonChange();renderHeader();renderArchive();renderSavedStats();toast('Stagione selezionata')};$('addSeasonBtn').onclick=addSeason;$('renameSeasonBtn').onclick=renameSeason;$('deleteSeasonBtn').onclick=deleteSeason;
// dialog close buttons
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));
$('sTeamLogo').onchange=()=>readImage($('sTeamLogo'),v=>{state.settings.teamLogo=v;$('teamLogoPreview').innerHTML=`<img src="${v}">`;save()});$('sOppLogo').onchange=()=>readImage($('sOppLogo'),v=>{state.opponent.logo=v;$('oppLogoPreview').innerHTML=`<img src="${v}">`;save()});
